head.script:
scwin.gVar = {
    "cStyle" : "",
    "cStyleParent" : "",
}


scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof parent1 !== 'undefined') {
        parent1.remove();
    }

    // 조건 설정
    let cStyle = scwin.gVar["cStyle"];
    let cStyleParent = scwin.gVar["cStyleParent"];

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strNameSpace = $c.gcm.getNameSpace();

    let strParent = '';
    strParent += '<xf:group ' + strNameSpace + ' style="background-color:var(--ws-green-100); height: 400px; '+cStyleParent+'">';
    strParent += '</xf:group>';

    scwin.parent1 = await $p.dynamicCreate(
        "parent1",
        "group",
        strParent,
        grp_comp
    );

    // scrollView 생성
    let strTarget = '';
    strTarget += '<w2:scrollView ' + strNameSpace + ' id="" style="width:500px; height:300px; ' + cStyle + '">';
    strTarget += '</w2:scrollView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "scrollView",
        strTarget,
        parent1
    );

    // scrollView 내부 자식 생성 (회원 정보 입력 폼 : 제목 + 입력 5행 + 약관 안내 + 버튼 행 → 세로 스크롤 발생)
    //  - container DOM("{id}_container")을 parent 로 지정, 자식 ID 는 자동 부여(재생성 시 중복 ID 방지)
    let containerDom = document.getElementById(scwin.target1.id + "_container");
    if (containerDom === null) {
        containerDom = scwin.target1.dom.container;
    }

    let strTitle = '<w2:textbox ' + strNameSpace + ' id="" label="회원 정보 입력" style="height:30px; line-height:30px; font-weight:bold; border-bottom:1px solid #cccccc; margin-bottom:6px;"></w2:textbox>';
    await $p.dynamicCreate('', 'textbox', strTitle, containerDom);

    let arrRow = [
        ["이름", "홍길동"],
        ["이메일", "hong@inswave.com"],
        ["연락처", "010-1234-5678"],
        ["주소", "서울특별시 강남구 테헤란로 123"],
        ["회사", "인스웨이브시스템즈"]
    ];

    for (let i = 0; i < arrRow.length; i++) {
        let strRow = '<xf:group ' + strNameSpace + ' id="" style="height:34px; display:flex; align-items:center;"></xf:group>';
        let objRow = await $p.dynamicCreate('', 'group', strRow, containerDom);

        let strLabel = '<w2:textbox ' + strNameSpace + ' id="" label="' + arrRow[i][0] + '" style="width:80px; height:21px; line-height:21px;"></w2:textbox>';
        await $p.dynamicCreate('', 'textbox', strLabel, objRow);

        let strInput = '<xf:input ' + strNameSpace + ' id="" style="width:300px; height:21px;" initValue="' + arrRow[i][1] + '"></xf:input>';
        await $p.dynamicCreate('', 'input', strInput, objRow);
    }

    let strTermsTitle = '<w2:textbox ' + strNameSpace + ' id="" label="개인정보 수집 및 이용 안내" style="height:30px; line-height:30px; margin-top:8px; font-weight:bold;"></w2:textbox>';
    await $p.dynamicCreate('', 'textbox', strTermsTitle, containerDom);

    let strTerms = '<xf:group ' + strNameSpace + ' id="" style="width:440px; height:160px; padding:8px; border:1px solid #cccccc; background-color:#f7f7f7; box-sizing:border-box;"></xf:group>';
    let objTerms = await $p.dynamicCreate('', 'group', strTerms, containerDom);

    let strTermsText = '<w2:textbox ' + strNameSpace + ' id="" label="1. 수집 항목 : 이름, 이메일, 연락처, 주소, 회사&#10;2. 수집 목적 : 회원 관리 및 서비스 안내&#10;3. 보유 기간 : 회원 탈퇴 시까지&#10;4. 동의를 거부할 수 있으며, 거부 시 회원 가입이 제한됩니다." style="white-space:pre-line; line-height:22px;"></w2:textbox>';
    await $p.dynamicCreate('', 'textbox', strTermsText, objTerms);

    let strBtnRow = '<xf:group ' + strNameSpace + ' id="" style="height:40px; margin-top:8px; display:flex; align-items:center; gap:6px;"></xf:group>';
    let objBtnRow = await $p.dynamicCreate('', 'group', strBtnRow, containerDom);

    let strButton1 = '<w2:button ' + strNameSpace + ' id="" style="width:80px; height:23px;" label="저장"></w2:button>';
    await $p.dynamicCreate('', 'button', strButton1, objBtnRow);

    let strButton2 = '<w2:button ' + strNameSpace + ' id="" style="width:80px; height:23px;" label="취소"></w2:button>';
    await $p.dynamicCreate('', 'button', strButton2, objBtnRow);
}
